using System.Reflection;
using System.Text;

namespace Raffica.Pdf.Packaging;

/// <summary>
/// The notices of the third-party components, generated by <c>tools/licenses.cs</c> and embedded in the app as
/// <c>Resources/ThirdPartyNotices.txt</c>. The text is read from the assembly only when <see cref="Read"/> is called (the About card),
/// never at startup, and it is not kept: the card holds the one copy it shows.
/// </summary>
internal static class ThirdPartyNotices
{
    private const string ResourceName = "Raffica.Pdf.ThirdPartyNotices.txt";

    /// <summary>Reads the embedded notices text; throws <see cref="InvalidOperationException"/> when the resource is missing.</summary>
    public static string Read()
    {
        using var stream = typeof(ThirdPartyNotices).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException("The notices resource is missing: " + ResourceName);
        using var reader = new StreamReader(stream, new UTF8Encoding(false));
        return reader.ReadToEnd();
    }
}
